struct PrinterA {
    void print(int x) const;
};

struct PrinterB {
    void print(int x) const;
};

// Compile-time polymorphic dispatcher template
template <typename T>
void execute_print(T obj, int val) {
    // Compiler selects the exact member function at compile time
    // No VTABLE required; direct static call possible
    std::invoke(&T::print, obj, val);
}

PrinterA pa;
PrinterB pb;

execute_print(pa, 10);
execute_print(pb, 20);
// Highly optimized: Monomorphization and potential inlining achieved.
